- [ ] **2. Create `src/jobs/weekly-agent-summary.js`.**
  ```js
  'use strict';
  // Nightly. Writes exports/agent-rating-summary.json: for each agent, how many ratings their tickets received
  // in the past seven days and the average score.
  const fs = require('node:fs');
  const path = require('node:path');

  const EXPORT_DIR = path.join(__dirname, '..', '..', 'exports');
  const DAY = 24 * 60 * 60 * 1000;
  const WINDOW_DAYS = 7;

  function weeklyAgentSummary(store, { now = new Date(), dir = EXPORT_DIR } = {}) {
    const since = now.getTime() - WINDOW_DAYS * DAY;
    const byAgent = new Map();
    for (const rating of store.listRatings()) {
      if (new Date(rating.rated_at).getTime() < since) continue;
      const ticket = store.getTicket(rating.ticket_id);
      if (!ticket || !ticket.owner_id) continue;
      const bucket = byAgent.get(ticket.owner_id) || { owner_id: ticket.owner_id, ratings_count: 0, total_score: 0 };
      bucket.ratings_count += 1;
      bucket.total_score += rating.score;
      byAgent.set(ticket.owner_id, bucket);
    }
    const rows = [...byAgent.values()]
      .map(({ owner_id, ratings_count, total_score }) => ({
        owner_id,
        ratings_count,
        average_score: Math.round((total_score / ratings_count) * 100) / 100,
      }))
      .sort((a, b) => a.owner_id - b.owner_id);
    fs.mkdirSync(dir, { recursive: true });
    const file = path.join(dir, 'agent-rating-summary.json');
    fs.writeFileSync(file, JSON.stringify(rows, null, 2) + '\n');
    return { file, rows };
  }

  module.exports = { weeklyAgentSummary, WINDOW_DAYS, EXPORT_DIR };
  ```
  Evidence: `node --test` — full suite passes.

